arguments.new_str:
namespace Warehouse;

public sealed class InventoryTracker
{
    private readonly Dictionary<string, Dictionary<string, int>> _warehouseStock = new();
    private readonly Dictionary<string, int> _reorderThresholds = new();

    private const string DefaultWarehouse = "default";

    public void SetReorderThreshold(string sku, int threshold)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        if (threshold < 0)
            throw new ArgumentOutOfRangeException(nameof(threshold));
        _reorderThresholds[sku] = threshold;
    }

    public int GetStockLevel(string sku)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        int total = 0;
        foreach (var warehouse in _warehouseStock.Values)
        {
            if (warehouse.TryGetValue(sku, out int qty))
                total += qty;
        }
        return total;
    }

    public int GetStockLevel(string sku, string warehouseId)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        ArgumentException.ThrowIfNullOrWhiteSpace(warehouseId);
        if (_warehouseStock.TryGetValue(warehouseId, out var stock) &&
            stock.TryGetValue(sku, out int qty))
            return qty;
        return 0;
    }

    public void AddStock(string sku, int quantity) =>
        AddStock(sku, quantity, DefaultWarehouse);

    public void AddStock(string sku, int quantity, string warehouseId)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        ArgumentException.ThrowIfNullOrWhiteSpace(warehouseId);
        if (quantity <= 0)
            throw new ArgumentOutOfRangeException(nameof(quantity));

        if (!_warehouseStock.TryGetValue(warehouseId, out var stock))
        {
            stock = new Dictionary<string, int>();
            _warehouseStock[warehouseId] = stock;
        }

        stock[sku] = stock.GetValueOrDefault(sku) + quantity;
    }

    public void RemoveStock(string sku, int quantity) =>
        RemoveStock(sku, quantity, DefaultWarehouse);

    public void RemoveStock(string sku, int quantity, string warehouseId)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        ArgumentException.ThrowIfNullOrWhiteSpace(warehouseId);
        if (quantity <= 0)
            throw new ArgumentOutOfRangeException(nameof(quantity));

        if (!_warehouseStock.TryGetValue(warehouseId, out var stock) ||
            !stock.TryGetValue(sku, out int current) ||
            current < quantity)
            throw new InvalidOperationException("Insufficient stock.");

        stock[sku] = current - quantity;
    }

    public bool NeedsReorder(string sku)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        if (!_reorderThresholds.TryGetValue(sku, out int threshold))
            return false;
        return GetStockLevel(sku) <= threshold;
    }

    public void Transfer(string sku, int quantity, string fromWarehouse, string toWarehouse)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        ArgumentException.ThrowIfNullOrWhiteSpace(fromWarehouse);
        ArgumentException.ThrowIfNullOrWhiteSpace(toWarehouse);
        if (quantity <= 0)
            throw new ArgumentOutOfRangeException(nameof(quantity));
        if (fromWarehouse == toWarehouse)
            throw new ArgumentException("Source and destination warehouses must differ.");

        RemoveStock(sku, quantity, fromWarehouse);
        AddStock(sku, quantity, toWarehouse);
    }
}

