        _tracker.AddStock("B", 8);
        Assert.AreEqual(3, _tracker.GetStockLevel("A"));
        Assert.AreEqual(8, _tracker.GetStockLevel("B"));
    }

    [TestMethod]
    public void RemoveStock_DecreasesLevel()
    {
        _tracker.AddStock("SKU-1", 10);
        _tracker.RemoveStock("SKU-1", 4);
        Assert.AreEqual(6, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void RemoveStock_AllStock_LevelBecomesZero()
    {
        _tracker.AddStock("SKU-1", 5);
        _tracker.RemoveStock("SKU-1", 5);
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void RemoveStock_InsufficientStock_Throws()
    {
        _tracker.AddStock("SKU-1", 3);
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-1", 5));
    }

    [TestMethod]
    public void RemoveStock_UnknownSku_Throws()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("NOPE", 1));
    }

    // ── Argument validation ─────────────────────────────────────

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddStock_InvalidSku_Throws(string? sku)
