    public void Transfer_SameWarehouse_Throws()
    {
        _tracker.AddStock("SKU-1", 10, "WH-East");
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.Transfer("SKU-1", 5, "WH-East", "WH-East"));
    }

