    {
        _tracker.AddStock("SKU-1", 10, "WH-A");
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.Transfer("SKU-1", qty, "WH-A", "WH-B"));
    }

    [TestMethod]
    public void Transfer_InsufficientStock_DoesNotAlterDestination()
    {
        _tracker.AddStock("SKU-1", 5, "WH-East");
        _tracker.AddStock("SKU-1", 3, "WH-West");

        try { _tracker.Transfer("SKU-1", 10, "WH-East", "WH-West"); }
        catch (InvalidOperationException) { }

        Assert.AreEqual(5, _tracker.GetStockLevel("SKU-1", "WH-East"));
        Assert.AreEqual(3, _tracker.GetStockLevel("SKU-1", "WH-West"));
    }

    // ── Reorder with warehouses ─────────────────────────────────

    [TestMethod]
    public void NeedsReorder_ConsidersTotalAcrossWarehouses()
    {
        _tracker.SetReorderThreshold("SKU-1", 10);
        _tracker.AddStock("SKU-1", 6, "WH-East");
        _tracker.AddStock("SKU-1", 6, "WH-West");

        Assert.IsFalse(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_AfterTransferReducesTotal_StillCorrect()
    {
        _tracker.SetReorderThreshold("SKU-1", 10);
        _tracker.AddStock("SKU-1", 15, "WH-East");

        Assert.IsFalse(_tracker.NeedsReorder("SKU-1"));

        _tracker.RemoveStock("SKU-1", 6, "WH-East");

        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }
}

